## 完整解决方案：拖拽过程中的实时轨迹展示

```javascript
class VehicleTrackManager {
    constructor(map) {
        this.map = map;
        this.vehicleCache = new Map(); // 全量数据缓存
        this.visibleVehicles = new Set(); // 当前可见车辆

        // 创建轨迹图层（启用空间索引）
        this.trackSource = new ol.source.Vector({
            useSpatialIndex: true,
            features: []
        });

        this.trackLayer = new ol.layer.Vector({
            source: this.trackSource,
            // 利用 OpenLayers 内置视口裁剪
            renderBuffer: 100 // 外扩 100 像素预加载
        });

        this.map.addLayer(this.trackLayer);

        // 节流更新（拖拽过程中）
        this.throttledUpdate = this.throttle(this.updateViewport.bind(this), 100);

        // 监听地图移动（高频事件）
        this.map.on('move', this.throttledUpdate);
    }

    // 添加车辆数据（全量缓存）
    addVehicle(vehicleId, trajectoryCoords) {
        this.vehicleCache.set(vehicleId, {
            coords: trajectoryCoords,
            feature: null,
            isVisible: false
        });
    }

    // 节流函数
    throttle(fn, delay) {
        let lastCall = 0;
        return (...args) => {
            const now = Date.now();
            if (now - lastCall >= delay) {
                lastCall = now;
                fn(...args);
            }
        };
    }

    // 更新视口内车辆
    updateViewport() {
        const extent = this.map.getView().calculateExtent(this.map.getSize());

        // 利用空间索引快速查询（O(log n)）
        const featuresInExtent = this.trackSource.getFeaturesInExtent(extent);
        const newVisibleSet = new Set(featuresInExtent.map(f => f.getId()));

        // 处理新进入视口的车辆
        this.vehicleCache.forEach((vehicle, id) => {
            const wasVisible = this.visibleVehicles.has(id);
            const nowVisible = newVisibleSet.has(id);

            if (!wasVisible && nowVisible) {
                // 新进入：显示轨迹
                this.showVehicleTrack(id);
            } else if (wasVisible && !nowVisible) {
                // 离开设口：隐藏轨迹（但保留数据）
                this.hideVehicleTrack(id);
            }
        });

        this.visibleVehicles = newVisibleSet;
    }

    showVehicleTrack(vehicleId) {
        const vehicle = this.vehicleCache.get(vehicleId);
        if (!vehicle.feature) {
            const feature = new ol.Feature({
                geometry: new ol.geom.LineString(vehicle.coords)
            });
            feature.setId(vehicleId);
            this.trackSource.addFeature(feature);
            vehicle.feature = feature;
        }
        vehicle.feature.setStyle(this.getTrackStyle());
    }

    hideVehicleTrack(vehicleId) {
        const vehicle = this.vehicleCache.get(vehicleId);
        if (vehicle.feature) {
            // 方案1：移除 Feature（节省渲染）
            this.trackSource.removeFeature(vehicle.feature);
            // 方案2：隐藏样式（保留 Feature，快速恢复）
            // vehicle.feature.setStyle(null);
        }
    }

    getTrackStyle() {
        // 样式缓存，避免每帧创建新对象
        return this._cachedStyle || (this._cachedStyle = new ol.style.Style({
            stroke: new ol.style.Stroke({
                color: '#3498db',
                width: 2
            })
        }));
    }
}
```

